window.products.push({"id":152518,"name":"297370600 Freezer User Control/Display Board Assembly for Frigidaire, Crosley Freezer Electronic Control Board -Replaces 297241800, 297366100","category":"homeandappliances","retail price":86.89,"sale price":null,"image":"https://m.media-amazon.com/images/I/61dJkV9KGAL._AC_SL1500_.jpg","description":"【Part Number】 297370600 (AP5318915) replaces 2020880, 297241800, 297345500, 297366100, AH3502428, EA3502428, PS3502428，WK40-09，451704000. 【Part Information】This electronic control board (part number 297370600) is for freezers. Electronic control board 297370600 manages the functions of the freezer such as the temperature settings and defrost cycle time. 【Compatible with】This part 297370600 is compatible with Frigidaire, Crosley Freezer FFU14F5HWB LFFU14F5HWC. 【Warm reminder】Safely store any food that could deteriorate while the power is off and unplug the freezer before installing this part. Wear work gloves to protect your hands.","images":["https://m.media-amazon.com/images/I/61dJkV9KGAL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"IURILA","source_asin":"B0C5M4XGT8","category_path":"Home & Appliances"},"sku":"BM-152518","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0C5M4XGT8","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B0C5M4XGT8","price_pending":true,"merchant_ready":false});
